import inspect
from functools import wraps
from robot.api import logger


def log_method_name(f):
    """
    :param f:
    :return:
    """
    @wraps(f)
    def wrapper(*args, **kwargs):
        """
        :param args:
        :param kwargs:
        :return:
        """
        keyword_name = f.__name__.replace('_', ' ').title()
        library_name = f.__module__
        a = inspect.getargspec(f)
        if a.defaults:
            defaults = dict(list(zip(reversed(a.args), reversed(a.defaults))))
        else:
            defaults = ''

        arg_list = []
        default_args = []
        for arg in list(args):
            if isinstance(arg, str):
                arg_list.append(arg)
        for key, value in list(kwargs.items()):
            arg_list.append('{}={}'.format(key, value))
        if isinstance(defaults, dict):
            for key, value in list(defaults.items()):
                default_args.append('{}={}'.format(key, value))

        logger.write('''<table bgcolor="yellow" border=1>
                    <tr><td>Keyword</td><td>{}</td></tr>
                    <tr><td>Library</td><td>{}</td></tr>
                    <tr><td>Parameters</td><td>{}</td></tr>
                    <tr><td>Default parameters</td><td>{}</td></tr>
                    </table>
                    '''.format(keyword_name, library_name, arg_list, default_args), level='HTML', html=True)

        result = f(*args, **kwargs)
        logger.write('<span style="color:blue"><b>{}.{} | Result: {}</span></b>'.format(library_name,
                                                                                        keyword_name,
                                                                                        result),
                     level='HTML', html=True)
        return result
    return wrapper
